let o = {
  [1]: 2
};

assert.sameValue(
  o[1],
  2
);
assert.sameValue(
  o[String(1)],
  2
);

let o = {
  ['1']: '2'
};

assert.sameValue(
  o['1'],
  '2'
);
assert.sameValue(
  o[String('1')],
  '2'
);

let x = 1;



let o = {
  [x]: '2'
};

assert.sameValue(
  o[x],
  '2'
);
assert.sameValue(
  o[String(x)],
  '2'
);

let o = {
  [true ? 1 : 2]: 2
};

assert.sameValue(
  o[true ? 1 : 2],
  2
);
assert.sameValue(
  o[String(true ? 1 : 2)],
  2
);

let o = {
  [false ? 1 : 2]: 1
};

assert.sameValue(
  o[false ? 1 : 2],
  1
);
assert.sameValue(
  o[String(false ? 1 : 2)],
  1
);

let o = {
  [1 + 1]: 2
};

assert.sameValue(
  o[1 + 1],
  2
);
assert.sameValue(
  o[String(1 + 1)],
  2
);

let o = {
  [1 - 1]: 0
};

assert.sameValue(
  o[1 - 1],
  0
);
assert.sameValue(
  o[String(1 - 1)],
  0
);

var counter = 0;
var o = {
  [++counter]: ++counter,
  [++counter]: ++counter,
  [++counter]: ++counter,
}

var keys = Object.getOwnPropertyNames(o);

assert.sameValue(keys.length, 3, '3 PropertyDefinitions should result in 3 properties');
assert.sameValue(keys[0], '1');
assert.sameValue(o[keys[0]], 2);
assert.sameValue(keys[1], '3');
assert.sameValue(o[keys[1]], 4);
assert.sameValue(keys[2], '5');
assert.sameValue(o[keys[2]], 6);

var value = "bad";

var key = {
  toString() {
    value = "ok";
    return "p";
  }
};

var obj = {
  [key]: value
};

assert.sameValue(obj.p, "ok");

var obj;
var sample = {};

obj = {
  ['__proto__']: sample
};
assert.sameValue(
  Object.getPrototypeOf(obj),
  Object.prototype,
  'does not change the object prototype (ordinary object)'
);
assert(
  obj.hasOwnProperty('__proto__'),
  'computed __proto__ property is set as an own property (ordinary object)'
);
assert.sameValue(
  obj.__proto__,
  sample,
  'value is properly defined (ordinary object)'
);

obj = {
  ['__proto__']: null
};
assert.sameValue(
  Object.getPrototypeOf(obj),
  Object.prototype,
  'does not change the object prototype (null)'
);
assert(
  obj.hasOwnProperty('__proto__'),
  'computed __proto__ property is set as an own property (null)'
);
assert.sameValue(
  obj.__proto__,
  null,
  'value is properly defined (null)'
);

obj = {
  ['__proto__']: undefined
};
assert.sameValue(
  Object.getPrototypeOf(obj),
  Object.prototype,
  'does not change the object prototype (undefined)'
);
assert(
